import{_ as o,c as s,o as i,j as n,Y as a,t as r}from"./chunks/framework.D-NV0Bun.js";const f=JSON.parse('{"title":"git-fsmonitor--daemon | x-cmd man (git man1) | A Built-in Filesystem Monitor","titleTemplate":false,"description":"x-cmd man (git man1 Manual Page) | git-fsmonitor--daemon - A Built-in Filesystem Monitor","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"git-fsmonitor--daemon | x-cmd man (git man1) | A Built-in Filesystem Monitor"}],["meta",{"name":"og:description","content":"x-cmd man (git man1 Manual Page) | git-fsmonitor--daemon - A Built-in Filesystem Monitor"}]]},"headers":[],"params":{"isMan":true,"man":"git-fsmonitor--daemon","category":"git man1","desc":"A Built-in Filesystem Monitor"},"relativePath":"git/man1/git-fsmonitor--daemon.md","filePath":"git/man1/[man].md"}'),l={name:"git/man1/git-fsmonitor--daemon.md"},h={class:"visually-hidden"};function d(e,t,c,m,p,g){return i(),s("div",null,[n("h1",h,r(e.$params.man),1),t[0]||(t[0]=a(`<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>git-fsmonitor--daemon - A Built-in Filesystem Monitor</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fsmonitor--daemon</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fsmonitor--daemon</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fsmonitor--daemon</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stop</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fsmonitor--daemon</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span></span></code></pre></div><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>A daemon to watch the working directory for file and directory changes using platform-specific filesystem notification facilities.</p><p>This daemon communicates directly with commands like <strong>git status</strong> using the <strong>simple IPC</strong>[1] interface instead of the slower <strong>githooks</strong>(5) interface.</p><p>This daemon is built into Git so that no third-party tools are required.</p><h2 id="options" tabindex="-1">OPTIONS <a class="header-anchor" href="#options" aria-label="Permalink to &quot;OPTIONS&quot;">​</a></h2><p>start</p><blockquote><p>Starts a daemon in the background.</p></blockquote><p>run</p><blockquote><p>Runs a daemon in the foreground.</p></blockquote><p>stop</p><blockquote><p>Stops the daemon running in the current working directory, if present.</p></blockquote><p>status</p><blockquote><p>Exits with zero status if a daemon is watching the current working directory.</p></blockquote><h2 id="remarks" tabindex="-1">REMARKS <a class="header-anchor" href="#remarks" aria-label="Permalink to &quot;REMARKS&quot;">​</a></h2><p>This daemon is a long running process used to watch a single working directory and maintain a list of the recently changed files and directories. Performance of commands such as <strong>git status</strong> can be increased if they just ask for a summary of changes to the working directory and can avoid scanning the disk.</p><p>When <strong>core.fsmonitor</strong> is set to <strong>true</strong> (see <strong>git-config</strong>(1)) commands, such as <strong>git status</strong>, will ask the daemon for changes and automatically start it (if necessary).</p><p>For more information see the &quot;File System Monitor&quot; section in <strong>git-update-index</strong>(1).</p><h2 id="caveats" tabindex="-1">CAVEATS <a class="header-anchor" href="#caveats" aria-label="Permalink to &quot;CAVEATS&quot;">​</a></h2><p>The fsmonitor daemon does not currently know about submodules and does not know to filter out filesystem events that happen within a submodule. If fsmonitor daemon is watching a super repo and a file is modified within the working directory of a submodule, it will report the change (as happening against the super repo). However, the client will properly ignore these extra events, so performance may be affected but it will not cause an incorrect result.</p><p>By default, the fsmonitor daemon refuses to work against network-mounted repositories; this may be overridden by setting <strong>fsmonitor.allowRemote</strong> to <strong>true</strong>. Note, however, that the fsmonitor daemon is not guaranteed to work correctly with all network-mounted repositories and such use is considered experimental.</p><p>On Mac OS, the inter-process communication (IPC) between various Git commands and the fsmonitor daemon is done via a Unix domain socket (UDS) --- a special type of file --- which is supported by native Mac OS filesystems, but not on network-mounted filesystems, NTFS, or FAT32. Other filesystems may or may not have the needed support; the fsmonitor daemon is not guaranteed to work with these filesystems and such use is considered experimental.</p><p>By default, the socket is created in the <strong>.git</strong> directory, however, if the <strong>.git</strong> directory is on a network-mounted filesystem, it will be instead be created at *<em>$HOME/.git-fsmonitor-*</em> * unless <strong>$HOME</strong> itself is on a network-mounted filesystem in which case you must set the configuration variable <strong>fsmonitor.socketDir</strong> to the path of a directory on a Mac OS native filesystem in which to create the socket file.</p><p>If none of the above directories (<strong>.git</strong>, <strong>$HOME</strong>, or <strong>fsmonitor.socketDir</strong>) is on a native Mac OS file filesystem the fsmonitor daemon will report an error that will cause the daemon and the currently running command to exit.</p><h2 id="configuration" tabindex="-1">CONFIGURATION <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;CONFIGURATION&quot;">​</a></h2><p>Everything below this line in this section is selectively included from the <strong>git-config</strong>(1) documentation. The content is the same as what&#39;s found there:</p><p>fsmonitor.allowRemote</p><blockquote><p>By default, the fsmonitor daemon refuses to work against network-mounted repositories. Setting <strong>fsmonitor.allowRemote</strong> to <strong>true</strong> overrides this behavior. Only respected when <strong>core.fsmonitor</strong> is set to <strong>true</strong>.</p></blockquote><p>fsmonitor.socketDir</p><blockquote><p>This Mac OS-specific option, if set, specifies the directory in which to create the Unix domain socket used for communication between the fsmonitor daemon and various Git commands. The directory must reside on a native Mac OS filesystem. Only respected when <strong>core.fsmonitor</strong> is set to <strong>true</strong>.</p></blockquote><h2 id="git" tabindex="-1">GIT <a class="header-anchor" href="#git" aria-label="Permalink to &quot;GIT&quot;">​</a></h2><p>Part of the <strong>git</strong>(1) suite</p><h2 id="notes" tabindex="-1">NOTES <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;NOTES&quot;">​</a></h2><ol><li></li></ol><p>: simple IPC</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">file:///usr/share/doc/git/technical/api-simple-ipc.html</span></span></code></pre></div>`,39))])}const k=o(l,[["render",d]]);export{f as __pageData,k as default};
